import {flattenBank,filterQuestions,selectionStats,validateSelection,orderedItems,moveItem,BLOOM,difficultyQuotas,autoSelect} from './core.mjs';
import {createExamPDFs} from './pdf.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let bank=[],topics=[],selected=[],target=50,view='bank',limit=20,busy=false,exportURLs=[],toastTimer,storageAvailable=true,logoDataUrl=null,logoLoading=false;
const STORAGE='pjpk-studio-v1';let restore=null;
try{restore=JSON.parse(localStorage.getItem(STORAGE)||'null');}catch{storageAvailable=false;}
const metadataFields=['school','exam-title','year','duration','teacher','reviewed-by','approved-by','teacher-role','reviewed-role','approved-role','instructions','cover','evidence-appendix'];
function getMeta(){return {school:$('school').value.trim(),title:$('exam-title').value.trim()||'UJIAN SUMATIF',year:$('year').value.trim(),duration:$('duration').value.trim(),teacher:$('teacher').value.trim(),reviewedBy:$('reviewed-by').value.trim(),approvedBy:$('approved-by').value.trim(),teacherRole:$('teacher-role').value.trim(),reviewedRole:$('reviewed-role').value.trim(),approvedRole:$('approved-role').value.trim(),logoDataUrl,instructions:$('instructions').value.trim(),cover:$('cover').checked,evidenceAppendix:$('evidence-appendix').checked};}
function storeDraft(){try{localStorage.setItem(STORAGE,JSON.stringify({selected,target,logoDataUrl,metadata:Object.fromEntries(metadataFields.map(id=>[id,['cover','evidence-appendix'].includes(id)?$(id).checked:$(id).value]))}));}catch{storageAvailable=false;document.querySelector('.local-note').textContent='Draf kekal sepanjang halaman ini dibuka.';}}
function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function filters(){return {form:$('form-filter').value,difficulties:[...document.querySelectorAll('[name=difficulty]:checked')].map(e=>e.value),topic:$('topic-filter').value,bloom:$('bloom-filter').value};}
function updateTopics(){const current=$('topic-filter').value,form=$('form-filter').value;const available=topics.filter(t=>(!form||t.form===Number(form))&&(!$('verified-only').checked||t.questions.some(q=>q.reviewStatus==='evidence-checked')));$('topic-filter').innerHTML='<option value="">Semua topik</option>'+available.map(t=>`<option value="${esc(t.id)}">${!form?'T'+t.form+' · ':''}${esc(t.title)}</option>`).join('');if(available.some(t=>t.id===current))$('topic-filter').value=current;}
function currentPool(){return filterQuestions(bank,filters()).filter(q=>!$('verified-only').checked||q.reviewStatus==='evidence-checked');}
function matching(){return view==='selected'?orderedItems(selected,bank):currentPool();}
function card(q,index=0){const chosen=selected.includes(q.id);const klass=q.difficulty==='Sederhana'?'medium':q.difficulty==='Tinggi'?'high':'';return `<article class="question-card${chosen?' selected':''}" data-id="${q.id}"><div class="card-meta"><span class="badge">T${q.form} · ${q.section}</span><span class="topic-name">${esc(q.topic)}</span><span class="badge ${klass}">${esc(q.difficulty)}</span><span class="proof-status${q.reviewStatus==='evidence-checked'?'':' pending'}">${q.reviewStatus==='evidence-checked'?'Bukti halaman':'Semakan diperlukan'}</span><span>C${q.bloom}${q.bloom>=4?' · KBAT':''}</span></div>${q.diagram?`<button class="diagram-zoom" data-zoom="${q.diagram}" aria-label="Besarkan rajah"><img class="diagram" src="./assets/Rajah_${q.diagram}.png" alt="Rajah ${q.diagram} untuk soalan ${q.id}" width="1530" height="435" loading="lazy"></button>`:''}<h2 class="q-stem"><span class="question-number">${index+1}.</span>${esc(q.stem)}</h2><ol class="options">${q.options.map((o,i)=>`<li><span class="option-letter">${'ABCD'[i]}</span><span>${esc(o)}</span></li>`).join('')}</ol><div class="card-bottom"><span class="quiet" style="font-size:12px">${q.id}</span><button class="select-question" data-select="${q.id}" aria-pressed="${chosen}" aria-label="${chosen?'Keluarkan':'Pilih'} soalan ${q.id}">${chosen?'✓ Dipilih':'+ Pilih soalan'}</button></div><details class="item-details"><summary>Jawapan & rujukan</summary><div class="details-content"><p><strong>${q.answer}. ${esc(q.correct)}</strong><br>${esc(q.reason)}</p><p>C${q.bloom} · ${BLOOM[q.bloom]}<br>Buku teks T${q.form}, hlm. ${esc(q.evidence?.printedPages||q.pages)}<br>${q.evidence?`PDF halaman ${q.evidence.pdfPage}<br>`:''}${q.curriculum?`DSKP (rujukan topik): ${esc(q.curriculum.codes)} · hlm. ${esc(q.curriculum.printedPages)}`:`Cadangan SK topik (belum disahkan): ${esc(q.sk)}`}</p>${q.evidence?`<button class="secondary evidence-button" data-evidence="${q.id}">Semak bukti halaman</button>`:'<p class="evidence-note">Rujukan julat topik sahaja. Jawapan belum disemak pada halaman khusus.</p>'}${q.distractorReasons?`<ul class="distractor-list">${q.options.map((o,i)=>o===q.correct?'':`<li><b>${'ABCD'[i]}:</b> ${esc(q.distractorReasons[o]||'Semak perbezaan dengan prinsip jawapan.')}</li>`).join('')}</ul>`:''}<a href="${esc(q.bookUrl)}" target="_blank" rel="noopener noreferrer">Buku teks</a><a href="${esc(q.dskpUrl)}" target="_blank" rel="noopener noreferrer">DSKP</a></div></details></article>`;}
function renderQuestions(){updateFilterSummary();const items=matching();$('result-count').textContent=items.length+' item'+(view==='selected'?' dalam kertas':' ditemui');if(!items.length){$('questions').innerHTML=`<div class="empty-state"><strong>${view==='selected'?'Belum ada soalan dipilih':'Tiada item sepadan'}</strong><p>${view==='selected'?'Pilih soalan daripada bank untuk membina kertas anda.':'Cuba tingkatan atau aras kesukaran yang lain.'}</p><button class="secondary" data-empty>${view==='selected'?'Kembali ke bank':'Tetap semula penapis'}</button></div>`;}else $('questions').innerHTML=items.slice(0,limit).map(card).join('');$('load-more').hidden=items.length<=limit;$('load-more').textContent='Paparkan lagi ('+(items.length-limit)+' baki)';}
function renderSummary(){const s=selectionStats(orderedItems(selected,bank));$('count').textContent=s.total;$('target-display').textContent=target;$('target').value=target;$('mobile-target').value=target;$('selected-tab-count').textContent=s.total;$('mobile-count').textContent=s.total+' / '+target;for(const [id,v]of [['low-count',s.low],['medium-count',s.medium],['high-count',s.high],['hots-count',s.hots]])$(id).textContent=v;$('progress').style.width=Math.min(100,s.total/target*100)+'%';const pb=document.querySelector('[role=progressbar]');pb.setAttribute('aria-valuemax',target);pb.setAttribute('aria-valuenow',s.total);$('remaining').textContent=s.total===target?'Sasaran lengkap. Kertas sedia untuk disemak.':`Pilih ${target-s.total} soalan lagi untuk melengkapkan kertas.`;for(const id of ['review-open','mobile-review','clear-open'])$(id).disabled=!s.total;}
function invalidateExport(){exportURLs.forEach(URL.revokeObjectURL);exportURLs=[];$('download-links').hidden=true;$('export-status').textContent='';}
function toggle(id){if(busy){notify('Tunggu sehingga PDF selesai disediakan.');return;}if(!bank.some(q=>q.id===id))throw Error('Soalan tidak ditemui.');if(selected.includes(id))selected=selected.filter(x=>x!==id);else {if(selected.length>=target){notify('Sasaran '+target+' soalan telah cukup. Ubah sasaran untuk menambah item.');return;}selected.push(id);}invalidateExport();storeDraft();renderSummary();if(view==='selected')renderQuestions();else{const c=document.querySelector(`.question-card[data-id="${id}"]`);if(c){const chosen=selected.includes(id);c.classList.toggle('selected',chosen);const b=c.querySelector('[data-select]');b.setAttribute('aria-pressed',chosen);b.setAttribute('aria-label',(chosen?'Keluarkan':'Pilih')+' soalan '+id);b.textContent=chosen?'✓ Dipilih':'+ Pilih soalan';}}if($('review-dialog').open)renderReview();}
function setView(v){view=v;limit=20;$('view-bank').classList.toggle('active',v==='bank');$('view-selected').classList.toggle('active',v==='selected');$('view-bank').setAttribute('aria-pressed',v==='bank');$('view-selected').setAttribute('aria-pressed',v==='selected');renderQuestions();}
function resetFilters(){ $('form-filter').value='2';$('verified-only').checked=true;syncFormBoxes();$('bloom-filter').value='';document.querySelectorAll('[name=difficulty]').forEach(e=>e.checked=false);updateTopics();$('topic-filter').value='';limit=20;setView('bank');}
function renderReview(){const items=orderedItems(selected,bank);$('review-count').textContent=items.length+' soalan · '+items.length+' markah';$('review-target-note').textContent=(items.length===target?'Nombor kertas mengikut susunan di bawah.':`${items.length} daripada sasaran ${target} dipilih. PDF akan mengandungi ${items.length} soalan.`)+(items.some(q=>q.reviewStatus!=='evidence-checked')?' PERHATIAN: '+items.filter(q=>q.reviewStatus!=='evidence-checked').length+' item belum disemak pada halaman khusus.':'');$('review-list').innerHTML=items.map((q,i)=>`<div class="review-item"><span class="review-no">${i+1}</span><div class="review-item-content"><p class="quiet">T${q.form} · ${esc(q.topic)} · ${esc(q.difficulty)}</p><p>${esc(q.stem)}</p><div class="review-actions"><button data-move="${q.id}" data-delta="-1" aria-label="Alih soalan ${i+1} ke atas" ${i===0?'disabled':''}>Naik</button><button data-move="${q.id}" data-delta="1" aria-label="Alih soalan ${i+1} ke bawah" ${i===items.length-1?'disabled':''}>Turun</button><button data-remove="${q.id}" aria-label="Keluarkan soalan ${i+1}">Keluarkan</button></div></div></div>`).join('');$('confirm-export').disabled=!items.length||busy||logoLoading;}
function openReview(){if(!selected.length)return;renderReview();$('review-dialog').showModal();}
function setBusy(value){busy=value;metadataFields.forEach(id=>$(id).disabled=value);$('confirm-export').disabled=value||!selected.length||logoLoading;$('school-logo').disabled=value;$('remove-logo').disabled=value;$('confirm-export').textContent=value?'Menyediakan PDF…':'Sahkan & sediakan PDF';$('review-list').querySelectorAll('button').forEach(b=>b.disabled=value|| (b.hasAttribute('data-move')&&(b.dataset.delta==='-1'?selected[0]===b.dataset.move:selected.at(-1)===b.dataset.move)));}
async function exportPDFs(){if(busy||logoLoading)return;invalidateExport();setBusy(true);$('export-status').textContent='Menyusun soalan, rajah dan skema…';try{const snapshot=orderedItems([...selected],bank);const meta=getMeta();const result=await createExamPDFs(snapshot,meta);const slug=(meta.title+'_'+meta.year).replace(/[^a-zA-Z0-9]+/g,'_').slice(0,70);for(const [id,bytes,name]of [['paper-download',result.paper,'Kertas_Murid'],['scheme-download',result.scheme,'Skema_Guru']]){const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));exportURLs.push(url);$(id).href=url;$(id).download=`PJPK_${slug}_${name}_${result.code}.pdf`;}$('download-links').hidden=false;$('export-status').textContent=`Sedia: kertas ${result.paperPages} halaman, skema ${result.schemePages} halaman. Kod ${result.code}.`;}catch(error){$('export-status').textContent='PDF belum dapat disediakan. '+(error.message||'Cuba sekali lagi.');}finally{setBusy(false);}}
function renderLogo(){ $('logo-preview-row').hidden=!logoDataUrl;if(logoDataUrl)$('logo-preview').src=logoDataUrl;else $('logo-preview').removeAttribute('src');}
async function normaliseLogo(file){
 if(!['image/png','image/jpeg'].includes(file.type))throw Error('Gunakan fail PNG atau JPG.');
 if(file.size>5*1024*1024)throw Error('Saiz logo melebihi 5 MB.');
 const url=URL.createObjectURL(file);
 try{const img=new Image();img.src=url;await img.decode();if(!img.naturalWidth||!img.naturalHeight)throw Error('Fail imej tidak sah.');const scale=Math.min(1,960/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');if(!ctx)throw Error('Imej tidak dapat diproses.');ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/png');}finally{URL.revokeObjectURL(url);}
}
$('school-logo').addEventListener('change',async()=>{const file=$('school-logo').files?.[0];if(!file)return;logoLoading=true;$('school-logo').disabled=true;$('confirm-export').disabled=true;$('remove-logo').disabled=true;$('logo-status').textContent='Memproses logo…';try{logoDataUrl=await normaliseLogo(file);$('cover').checked=true;renderLogo();invalidateExport();storeDraft();$('logo-status').textContent='Logo sedia. Nisbah asal dikekalkan.';}catch(error){$('logo-status').textContent=error.message||'Logo tidak dapat dibaca.';}finally{logoLoading=false;$('school-logo').disabled=busy;$('school-logo').value='';$('remove-logo').disabled=false;$('confirm-export').disabled=busy||!selected.length;}});
$('remove-logo').onclick=()=>{if(busy||logoLoading)return;logoDataUrl=null;renderLogo();invalidateExport();storeDraft();$('logo-status').textContent='Logo dibuang.';};
$('questions').addEventListener('click',event=>{const proof=event.target.closest('[data-evidence]');if(proof)showEvidence(proof.dataset.evidence);const zoom=event.target.closest('[data-zoom]');if(zoom){$('evidence-content').innerHTML=`<img class="diagram-large" src="./assets/Rajah_${esc(zoom.dataset.zoom)}.png" alt="Rajah soalan">`;$('evidence-dialog').showModal();}const button=event.target.closest('[data-select]');if(button)toggle(button.dataset.select);if(event.target.closest('[data-empty]')){if(view==='selected')setView('bank');else resetFilters();}});
$('review-list').addEventListener('click',event=>{if(busy)return;const move=event.target.closest('[data-move]'),remove=event.target.closest('[data-remove]');if(move){selected=moveItem(selected,move.dataset.move,Number(move.dataset.delta));invalidateExport();storeDraft();renderReview();if(view==='selected')renderQuestions();}if(remove)toggle(remove.dataset.remove);});
$('form-filter').addEventListener('change',()=>{syncFormBoxes();updateTopics();limit=20;setView('bank');});for(const id of ['topic-filter','bloom-filter'])$(id).addEventListener('change',()=>{limit=20;setView('bank');});document.querySelectorAll('[name=difficulty]').forEach(e=>e.addEventListener('change',()=>{limit=20;setView('bank');}));$('reset-filters').onclick=resetFilters;$('view-bank').onclick=()=>setView('bank');$('view-selected').onclick=()=>setView('selected');$('load-more').onclick=()=>{limit+=20;renderQuestions();};for(const targetId of ['target','mobile-target'])$(targetId).addEventListener('change',()=>{const v=Number($(targetId).value);try{validateSelection(selected,bank,v);target=v;storeDraft();renderSummary();}catch(error){$('target').value=target;$('mobile-target').value=target;notify(error.message);}});$('review-open').onclick=openReview;$('mobile-review').onclick=openReview;$('guide-open').onclick=()=>$('guide-dialog').showModal();$('clear-open').onclick=()=>$('clear-dialog').showModal();$('clear-confirm').onclick=()=>{if(busy)return;selected=[];invalidateExport();storeDraft();renderQuestions();renderSummary();$('clear-dialog').close();notify('Pilihan telah dikosongkan.');};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());metadataFields.forEach(id=>$(id).addEventListener('input',()=>{invalidateExport();storeDraft();}));$('confirm-export').onclick=exportPDFs;
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const options={signal:lifecycle.signal};const register=tool=>{try{Promise.resolve(context.registerTool(tool,options)).catch(()=>{});}catch{}};
register({name:'list_pjpk_questions',title:'Senarai soalan PJPK',description:'Read available questions and the current selection. Does not change the exam.',inputSchema:{type:'object',properties:{form:{type:'integer',minimum:2,maximum:5},difficulty:{type:'string',enum:['Rendah','Sederhana','Tinggi']}},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['form','difficulty'].includes(k))||(input.form!==undefined&&(!Number.isInteger(input.form)||input.form<2||input.form>5))||(input.difficulty!==undefined&&!['Rendah','Sederhana','Tinggi'].includes(input.difficulty)))throw Error('Penapis tidak sah.');return {selected:[...selected],target,questions:filterQuestions(bank,{form:input.form||'',difficulties:input.difficulty?[input.difficulty]:[]}).map(q=>({id:q.id,form:q.form,topic:q.topic,stem:q.stem,difficulty:q.difficulty,bloom:q.bloom}))};}});
register({name:'configure_pjpk_selection',title:'Pilih soalan peperiksaan',description:'Replace the draft selection with the supplied question IDs in order. Stages an exam; does not generate or download PDFs.',inputSchema:{type:'object',properties:{ids:{type:'array',items:{type:'string'},uniqueItems:true},target:{type:'integer',minimum:1,maximum:bank.length}},required:['ids','target'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(busy)throw Error('PDF sedang disediakan.');if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['ids','target'].includes(k)))throw Error('Input tidak sah.');validateSelection(input.ids,bank,input.target);selected=[...input.ids];target=input.target;invalidateExport();storeDraft();renderSummary();renderQuestions();if($('review-dialog').open)renderReview();return {selected:[...selected],target};}});
window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
function syncFormBoxes(){document.querySelectorAll('[data-form]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.form===$('form-filter').value)));}
function updateFilterSummary(){const f=filters();$('filter-summary').textContent=(f.form?'Tingkatan '+f.form:'Tingkatan 2–5')+' · '+($('topic-filter').selectedOptions[0]?.textContent||'Semua topik')+' · '+($('bloom-filter').selectedOptions[0]?.textContent||'Semua aras')+($('verified-only').checked?' · Bukti halaman sahaja':'');}
document.querySelectorAll('[data-form]').forEach(b=>b.onclick=()=>{$('form-filter').value=b.dataset.form;$('form-filter').dispatchEvent(new Event('change'));});
$('filter-toggle').onclick=()=>{const hidden=!$('filter-controls').hidden;$('filter-controls').hidden=hidden;$('filter-toggle').setAttribute('aria-expanded',String(!hidden));$('filter-toggle').textContent=hidden?'Ubah penapis':'Sembunyi penapis';};
$('verified-only').onchange=()=>{updateTopics();limit=20;setView('bank');};
function quotaPercentages(){return ['low','medium','high'].map(k=>Number($('pct-'+k).value));}
function refreshQuotas(){try{const q=difficultyQuotas(Number($('auto-target').value),quotaPercentages());['low','medium','high'].forEach((k,i)=>$('quota-'+k).textContent=q[i]);$('quota-status').textContent='100% · '+q.reduce((a,b)=>a+b,0)+' soalan';$('auto-generate').disabled=false;}catch(e){$('quota-status').textContent=e.message;$('auto-generate').disabled=true;['low','medium','high'].forEach(k=>$('quota-'+k).textContent='–');}}
for(const key of ['low','medium','high'])for(const kind of ['pct','range'])$(kind+'-'+key).oninput=()=>{$((kind==='pct'?'range':'pct')+'-'+key).value=$(kind+'-'+key).value;refreshQuotas();};
$('auto-target').oninput=refreshQuotas;
$('auto-open').onclick=()=>{$('auto-target').value=target;$('auto-error').textContent='';const pool=currentPool();$('auto-scope').textContent=$('filter-summary').textContent+' · '+pool.length+' item tersedia. Rendah '+pool.filter(q=>q.difficulty==='Rendah').length+', sederhana '+pool.filter(q=>q.difficulty==='Sederhana').length+', tinggi '+pool.filter(q=>q.difficulty==='Tinggi').length+'.';refreshQuotas();$('auto-dialog').showModal();};
$('auto-generate').onclick=()=>{if(busy)return;try{const n=Number($('auto-target').value);const ids=autoSelect(currentPool(),n,quotaPercentages(),$('auto-keep').checked?selected:[]);validateSelection(ids,bank,n);selected=ids;target=n;invalidateExport();storeDraft();renderQuestions();renderSummary();$('auto-dialog').close();openReview();}catch(e){$('auto-error').textContent=e.message;}};
function showEvidence(id){const q=bank.find(q=>q.id===id);if(!q?.evidence)return;const e=q.evidence;$('evidence-content').innerHTML=`<p><strong>${esc(q.id)} · ${esc(q.topic)}</strong></p><p>Buku teks PJPK Tingkatan ${q.form} · hlm. ${esc(e.printedPages)} · PDF halaman ${e.pdfPage}</p><p class="evidence-note">${esc(e.explanation)}</p>${(e.snippets||[]).map(path=>`<a href="./assets/evidence/${esc(path)}" target="_blank" rel="noopener noreferrer"><img class="evidence-preview" src="./assets/evidence/${esc(path)}" alt="Buka petikan buku teks halaman ${esc(e.printedPages)} pada saiz penuh" loading="lazy"></a>`).join('')}<p><strong>Jawapan ${q.answer}:</strong> ${esc(q.reason)}</p><p>Ketik petikan untuk membuka saiz penuh dan zum.</p><p>SP pada buku teks: ${esc(e.sp||'Tidak dinyatakan pada petikan ini')}. ${q.curriculum?`DSKP berkaitan: ${esc(q.curriculum.codes)} · hlm. ${esc(q.curriculum.printedPages)}. Rujukan ini disemak pada peringkat topik; soalan objektif menilai pengetahuan, bukan penguasaan amali.`:'Pemetaan DSKP berasingan masih perlu disahkan.'}</p><p>Situasi soalan ialah binaan asal. Petikan ini digunakan untuk menyemak prinsip jawapan.</p>`;$('evidence-dialog').showModal();}
try{const response=await fetch(new URL('./assets/bank.json',import.meta.url));if(!response.ok)throw Error('Bank tidak dapat dimuatkan.');const data=await response.json();bank=flattenBank(data).filter(q=>q.form>=2);topics=data.topics.filter(t=>t.form>=2);for(const id of ['target','mobile-target','auto-target'])$(id).max=bank.length;$('bank-total').textContent=bank.filter(q=>q.reviewStatus==='evidence-checked').length+' bukti halaman · '+bank.length+' jumlah';if(restore){selected=Array.isArray(restore.selected)?[...new Set(restore.selected)].filter(id=>bank.some(q=>q.id===id)):[];target=Number.isInteger(restore.target)&&restore.target>0&&restore.target<=bank.length?Math.max(restore.target,selected.length):Math.max(50,selected.length);for(const id of metadataFields){const v=restore.metadata?.[id];if(['cover','evidence-appendix'].includes(id)){if(typeof v==='boolean')$(id).checked=v;}else if(typeof v==='string')$(id).value=v.slice(0,$(id).maxLength);}if(typeof restore.logoDataUrl==='string'&&restore.logoDataUrl.startsWith('data:image/png;base64,')&&restore.logoDataUrl.length<6000000)logoDataUrl=restore.logoDataUrl;}renderLogo();updateTopics();renderQuestions();renderSummary();if(selected.some(id=>bank.find(q=>q.id===id)?.reviewStatus!=='evidence-checked'))notify('Draf dipulihkan mengandungi item lama. Semak rujukan sebelum mencetak.');if(!storageAvailable)document.querySelector('.local-note').textContent='Draf kekal sepanjang halaman ini dibuka.';registerTools();}catch(error){$('questions').innerHTML='<div class="empty-state"><strong>Bank belum dapat dimuatkan</strong><p>Semak sambungan dan muat semula halaman.</p><button class="secondary" id="retry-load">Muat semula</button></div>';$('result-count').textContent='Tidak tersedia';$('retry-load').onclick=()=>location.reload();}
